#!/usr/bin/env node
import { spawn } from 'node:child_process';
import { mkdir, readdir, readFile, stat } from 'node:fs/promises';
import path from 'node:path';
import process from 'node:process';
import { fileURLToPath } from 'node:url';

const packageRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const skillRoot = path.join(packageRoot, 'setup', '.agents', 'skills', 'scaffold');
const KNOWN_TOOLS = ['claude', 'codex'];

function parseArgs(argv) {
  let tool = null;
  const positional = [];

  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];
    if (arg === '--tool') {
      tool = argv[i + 1];
      i += 1;
    } else if (arg.startsWith('--tool=')) {
      tool = arg.slice('--tool='.length);
    } else {
      positional.push(arg);
    }
  }

  return { tool, target: positional[0] || '.' };
}

function commandExists(cmd) {
  return new Promise((resolve) => {
    const probe = spawn(cmd, ['--version'], { stdio: 'ignore' });
    probe.on('error', () => resolve(false));
    probe.on('exit', (code) => resolve(code !== null));
  });
}

async function detectTool(preferred) {
  if (preferred) {
    if (!KNOWN_TOOLS.includes(preferred)) {
      throw new Error(`Unknown --tool "${preferred}". Expected one of: ${KNOWN_TOOLS.join(', ')}.`);
    }
    if (!(await commandExists(preferred))) {
      throw new Error(`Requested tool "${preferred}" was not found on PATH.`);
    }
    return preferred;
  }

  for (const candidate of KNOWN_TOOLS) {
    if (await commandExists(candidate)) {
      return candidate;
    }
  }

  throw new Error(
    `Neither "${KNOWN_TOOLS.join('" nor "')}" was found on PATH. Install one of them and try again, ` +
      `or pass --tool explicitly.`,
  );
}

async function buildPrompt(targetDir) {
  const skillText = await readFile(path.join(skillRoot, 'SKILL.md'), 'utf8');
  const referencesDir = path.join(skillRoot, 'references');

  let referenceListing = '(none)';
  if (await stat(referencesDir).catch(() => null)) {
    const entries = await readdir(referencesDir);
    referenceListing = entries.map((name) => `- ${path.join(referencesDir, name)}`).join('\n');
  }

  return [
    'Act as the "scaffold" skill and follow the instructions below exactly to scaffold a brand-new project.',
    '',
    `Target directory: ${targetDir} (create it if it does not already exist; this is the new project root).`,
    '',
    'The guide table below refers to paths under ".agents/skills/scaffold/references/" — that directory ' +
      'does not exist in the target project. Use these absolute paths on this machine instead, matched by filename:',
    referenceListing,
    '',
    'Do not copy the guide files, this skill file, any other shipyard skill, AGENTS.md, CLAUDE.md, or ' +
      'prompt-library content into the target directory. When scaffolding finishes, the target directory must ' +
      'contain only the scaffolded project itself — nothing shipyard-specific.',
    '',
    '--- scaffold SKILL.md ---',
    skillText,
  ].join('\n');
}

export async function run(argv) {
  const { tool, target } = parseArgs(argv);
  const targetDir = path.resolve(process.cwd(), target);
  await mkdir(targetDir, { recursive: true });

  const resolvedTool = await detectTool(tool);
  const prompt = await buildPrompt(targetDir);

  console.log(`shipyard scaffold: launching "${resolvedTool}" in ${targetDir}`);

  await new Promise((resolve, reject) => {
    const child = spawn(resolvedTool, [prompt], { cwd: targetDir, stdio: 'inherit' });
    child.on('error', reject);
    child.on('exit', (code, signal) => {
      if (signal) {
        reject(new Error(`${resolvedTool} exited via signal ${signal}`));
      } else if (code === 0) {
        resolve();
      } else {
        reject(new Error(`${resolvedTool} exited with code ${code}`));
      }
    });
  });
}
